import { motion } from 'motion/react'
import { useGesture } from '../core/useGesture'
import { svgDefaults, type GestureIconProps } from '../core/types'
import { easeInOutCubic, settleBack } from '../core/easings'

/**
 * Minimize — it pulls inward. Mirror of maximize: both corner marks NUDGE
 * toward the center along their own diagonal — wind up outward first, then
 * drive in past the mark, settle back home — on the same clock.
 * Base geometry: Lucide `minimize-2` (ISC).
 */
const DUR = 0.75
const D = 0.7071
const DRIVE = 2.2
const WIND = 0.6

export function MinimizeIcon({
  size = 24, color = 'currentColor', strokeWidth = 2,
  trigger, className, style, handleRef, ...rest
}: GestureIconProps) {
  const { controls, hoverProps } = useGesture({ trigger, handleRef })
  return (
    <svg
      {...svgDefaults} width={size} height={size} stroke={color} strokeWidth={strokeWidth}
      className={className} style={style} role="img" aria-label={rest['aria-label'] ?? 'minimize'}
      {...hoverProps}
    >
      {/* top-right corner nudges inward toward center */}
      <motion.g
        initial="normal"
        animate={controls}
        variants={{
          normal: { x: 0, y: 0 },
          animate: {
            x: [0, WIND * D, -DRIVE * D, 0],
            y: [0, -WIND * D, DRIVE * D, 0],
            transition: { duration: DUR, times: [0, 0.2, 0.55, 1], ease: [easeInOutCubic, settleBack, easeInOutCubic] },
          },
        }}
      >
        <path d="m14 10 7-7" />
        <path d="M20 10h-6V4" />
      </motion.g>
      {/* bottom-left corner nudges inward toward center */}
      <motion.g
        initial="normal"
        animate={controls}
        variants={{
          normal: { x: 0, y: 0 },
          animate: {
            x: [0, -WIND * D, DRIVE * D, 0],
            y: [0, WIND * D, -DRIVE * D, 0],
            transition: { duration: DUR, times: [0, 0.2, 0.55, 1], ease: [easeInOutCubic, settleBack, easeInOutCubic] },
          },
        }}
      >
        <path d="m3 21 7-7" />
        <path d="M4 14h6v6" />
      </motion.g>
    </svg>
  )
}

export const meta = {
  name: 'minimize',
  gesture: 'it pulls inward',
  family: 'rigid' as const,
  section: 'Arrows',
  tags: ['restore', 'collapse'],
}

export default MinimizeIcon
